const $=id=>document.getElementById(id);let orders=[],selectedId=null,previewUrl=null;
const labels={prepared:'Klar til afsendelse',gateway_accepted:'Modtaget af PF',awaiting_proof:'Afventer korrektur',proof_received:'Til gennemgang',approval_pending_pf:'Smerch har godkendt · afventer PF',revision_requested:'Ændring ønsket',approval_recorded:'Godkendelse registreret hos PF',processing:'PF behandler ordren',shipped:'Afsendt',needs_attention:'Kræver opmærksomhed',needs_reconciliation:'Afstem med PF',cancelled:'Annulleret'};
function el(tag,txt,cls){const node=document.createElement(tag);if(txt!=null)node.textContent=String(txt);if(cls)node.className=cls;return node;}
function say(message){$('feedback').textContent=message||'';}
async function api(path,method='GET',body){const response=await fetch(path,{method,credentials:'same-origin',headers:{...(method!=='GET'?{'X-Smerch-Admin':'1'}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined,cache:'no-store'});if(!response.ok){let problem;try{problem=await response.json();}catch{}throw Error(problem?.error||`HTTP ${response.status}`);}return response;}
async function refresh(){try{orders=await (await api('/api/pf-orders')).json();$('login').hidden=true;$('gateway-test').hidden=false;$('workspace').hidden=false;$('refresh').hidden=false;$('logout').hidden=false;renderList();if(selectedId)await show(selectedId);else if(orders[0])await show(orders[0].id);say('');}catch(error){say(error.message);if(error.message.includes('Administratoradgang')){$('login').hidden=false;$('gateway-test').hidden=true;$('workspace').hidden=true;$('refresh').hidden=true;$('logout').hidden=true;}}}
function renderList(){const area=$('orders');area.replaceChildren();const filter=$('filter').value;for(const order of orders.filter(row=>filter==='all'||row.status===filter)){const button=el('button',null,'order'+(order.id===selectedId?' active':''));button.type='button';button.append(el('strong',order.purchaseOrderNumber),el('span',labels[order.status]||order.status,'pill'),el('small',new Date(order.updatedAt).toLocaleString('da-DK')));button.onclick=()=>show(order.id);area.append(button);}if(!area.childElementCount)area.append(el('p','Ingen ordrer i dette filter.','muted'));}
async function show(id){selectedId=id;renderList();const order=await (await api(`/api/pf-orders/${id}`)).json(),checkout=order.checkoutId?await api(`/api/checkout/${order.checkoutId}`).then(response=>response.json()).catch(()=>null):null,box=$('detail');box.replaceChildren();if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}box.append(el('h2',order.purchaseOrderNumber),el('p',labels[order.status]||order.status,'pill'));if(checkout)box.append(el('p',`Smerch-ordre ${checkout.id} · betaling: ${checkout.status==='paid'?'hævet':checkout.status==='authorized'?'reserveret, ikke hævet':checkout.status}`,'muted'));
 const isTest=order.gatewayPayload?.Header?.isTest===true,hasDecorations=order.lines?.some(line=>line.decorations?.length);if(isTest)box.append(el('p','PF-testordre · ingen betaling · kan ikke frigives til produktion','status ready'));
 const facts=el('div',null,'facts');for(const [label,value] of [['Miljø',isTest?'PF test':'PF produktion'],['PF-ordrenr.',order.pfOrderNumber||'Afventer PF-bekræftelse'],['Produkter',order.lines?.map(line=>line.productId).join(', ')||'—'],['Antal',order.lines?.reduce((sum,line)=>sum+line.quantity,0)||0],['Placeringer',order.lines?.reduce((sum,line)=>sum+line.decorations.length,0)||0],['Kundepris inkl. moms',order.quote?.totalIncVat!=null?(order.quote.totalIncVat/100).toLocaleString('da-DK',{style:'currency',currency:'DKK'}):'—'],['Senest opdateret',new Date(order.updatedAt).toLocaleString('da-DK')]]){const card=el('div');card.append(el('span',label),el('strong',value));facts.append(card);}box.append(facts);for(const line of order.lines||[]){const section=el('section');section.append(el('h3',`${line.quantity} × ${line.productId} · ${line.sku}`));for(const decoration of line.decorations){section.append(el('p',`${decoration.method} · ${decoration.position} · ${decoration.colors} farve${decoration.colors===1?'':'r'} · ${decoration.width} × ${decoration.height} mm · ${decoration.pmsColors?.join(', ')||'Farver afventer'}`));if(decoration.text)section.append(el('p',`Tekst: ${decoration.text}`));if(order.checkoutId)for(const art of decoration.artworks||[]){const a=el('a',`Hent originalfil: ${art.logo.name} ↓`);a.href=`/api/admin/checkouts/${order.checkoutId}/artwork/${art.logo.id}`;a.className='action light';section.append(a);}}box.append(section);}if(order.proofs?.length){const section=el('section');section.append(el('h3','Alle korrekturversioner'));for(const proof of order.proofs){const a=el('a',`Version ${proof.version} · ${proof.reference} · ${new Date(proof.receivedAt).toLocaleString('da-DK')}`);a.href=proof.mimeType?`/api/pf-orders/${id}/proof-file?version=${proof.version}`:proof.url;a.target='_blank';a.rel='noopener noreferrer';section.append(a,document.createElement('br'));}box.append(section);}
 if(order.proof){box.append(el('h2',`Korrektur version ${order.proof.version}`));box.append(el('p',`PF-reference: ${order.proof.reference}`));const preview=el('div',null,'preview');box.append(preview);if(order.proof.mimeType){try{const response=await api(`/api/pf-orders/${id}/proof-file?version=${order.proof.version}`),blob=await response.blob();previewUrl=URL.createObjectURL(blob);const media=document.createElement(order.proof.mimeType==='application/pdf'?'iframe':'img');media.src=previewUrl;media.title='PF-korrektur';preview.append(media);}catch(error){preview.append(el('p',error.message));}}else if(order.proof.url){const link=el('a','Åbn korrektur hos PF ↗');link.href=order.proof.url;link.target='_blank';link.rel='noopener noreferrer';preview.append(link);}}
 if(hasDecorations&&['gateway_accepted','awaiting_proof','proof_received','revision_requested','approval_pending_pf'].includes(order.status)){const section=el('section');section.append(el('h2','Tilføj korrektur'));const ref=el('input');ref.placeholder='PF-korrekturreferencen';ref.setAttribute('aria-label','PF-korrekturreferencen');const upload=el('input');upload.type='file';upload.accept='.pdf,.png,.jpg,.jpeg';upload.setAttribute('aria-label','Korrekturfil');const button=el('button','Gem korrektur');button.onclick=async()=>{try{if(!upload.files[0])throw Error('Vælg en korrekturfil.');const file=upload.files[0];if(file.size>10*1024*1024)throw Error('Filen må højst være 10 MB.');const contentBase64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(reader.error);reader.readAsDataURL(file);});await api(`/api/pf-orders/${id}/proof`,'POST',{proofReference:ref.value,mimeType:file.type,contentBase64});await refresh();}catch(error){say(error.message);}};section.append(ref,upload,button);box.append(section);}
 if(order.status==='proof_received'){const area=el('div');area.append(el('h2','Beslutning'));const note=el('textarea');note.placeholder='Kommentar til PF ved ændringsønske';note.setAttribute('aria-label','Kommentar til PF');const buttons=el('div',null,'actions');for(const [decision,text,cls] of [['approve','Godkend hos Smerch','primary'],['reject','Bed om ændring','danger']]){const button=el('button',text,cls);button.disabled=decision==='approve'&&checkout&&!['authorized','paid'].includes(checkout.status);button.onclick=async()=>{try{const result=await (await api(`/api/pf-orders/${id}/decision`,'POST',{version:order.proof.version,decision,comment:note.value})).json();await refresh();if(result.captureIssue)say(`Korrekturen er godkendt, men betalingen er ikke hævet: ${result.captureIssue}`);}catch(error){say(error.message);}};buttons.append(button);}area.append(note,buttons,el('p','Ved godkendelse hæves betalingen, når alle korrekturer på kundeordren er godkendt. Send først godkendelsen til PF efter bekræftet hævning.','muted'));box.append(area);}
 if(order.decision){box.append(el('h2','Smerchs beslutning'),el('p',order.decision.decision==='approve'?'Godkendt internt. Afventer afsendelse og PF-kvittering.':'Ændring ønsket. Afventer ny PF-korrektur.'));if(order.decision.comment)box.append(el('p',order.decision.comment));}
 if(order.status==='approval_pending_pf'&&checkout?.status==='authorized'){const capture=el('button','Hæv godkendt betaling','primary');capture.onclick=async()=>{try{await api(`/api/admin/checkouts/${order.checkoutId}/capture`,'POST');await refresh();}catch(error){say(error.message);}};box.append(capture,el('p','Hævning kræver, at alle PF-korrekturer for kundeordren er godkendt, og reservationen stadig er gyldig.','muted'));}
 if(order.status==='approval_pending_pf'||order.status==='revision_requested'){const area=el('section');area.append(el('h2','Besked til PF'));const copy=el('button','Kopiér beslutning');copy.disabled=Boolean(order.checkoutId&&order.decision.decision==='approve'&&checkout?.status!=='paid');copy.onclick=async()=>{const message=[`Smerch-ordre: ${order.purchaseOrderNumber}`,`PF-ordre: ${order.pfOrderNumber||'ukendt'}`,`Korrektur: ${order.proof.reference} (version ${order.proof.version})`,order.decision.decision==='approve'?'Beslutning: Vi godkender denne korrektur og ønsker produktionen bekræftet.':`Beslutning: Vi ønsker en ny korrektur. ${order.decision.comment}`,'Bekræft venligst modtagelse med jeres reference.'].join('\n');try{await navigator.clipboard.writeText(message);say('Beskeden er kopieret. Send den gennem den aftalte PF-kanal.');}catch{say('Kunne ikke kopiere. Brug PF’s aftalte kanal manuelt.');}};area.append(copy,el('p',copy.disabled?'Betalingen er endnu ikke hævet. Godkendelsen må ikke sendes til PF.':'Afsend gennem den aftalte PF-kanal. Denne knap sender ikke automatisk noget til PF.','muted'));box.append(area);}
 if(['approval_pending_pf','revision_requested'].includes(order.status)&&(!order.checkoutId||order.decision?.decision==='reject'||checkout?.status==='paid')&&!order.decision.delivery?.reference){const area=el('section');area.append(el('h2',order.decision.decision==='approve'?'Registrér godkendelse sendt til PF':'Registrér ændringsønske sendt til PF'));const channel=el('select');for(const name of ['PF Store','E-mail','Anden aftalt PF-kanal']){const option=el('option',name);option.value=name;channel.append(option);}const reference=el('input');reference.placeholder='Afsendelsesreference eller besked-id';reference.setAttribute('aria-label','Afsendelsesreference');const button=el('button','Registrér afsendelse');button.onclick=async()=>{try{await api(`/api/pf-orders/${id}/approval-delivery`,'POST',{channel:channel.value,reference:reference.value});await refresh();}catch(error){say(error.message);}};area.append(channel,reference,button,el('p','Send først beslutningen gennem den aftalte PF-kanal. Registreringen sender ikke selv noget.','muted'));box.append(area);}if(order.decision?.delivery?.reference)box.append(el('p',`Godkendelse sendt via ${order.decision.delivery.channel} · ${order.decision.delivery.reference}`));
 if(order.status==='approval_pending_pf'){const area=el('section');area.append(el('h2','PF-kvittering'));const reference=el('input');reference.placeholder='PF’s godkendelsesreference';reference.setAttribute('aria-label','PF’s godkendelsesreference');const button=el('button','Registrér bekræftelse fra PF');button.disabled=Boolean(order.checkoutId&&(checkout?.status!=='paid'||!order.decision.delivery?.reference));button.onclick=async()=>{try{await api(`/api/pf-orders/${id}/external-approval`,'POST',{pfApprovalReference:reference.value});await refresh();}catch(error){say(error.message);}};area.append(reference,button,el('p','Brug kun dette felt, når PF faktisk har kvitteret for godkendelsen, og kundens betaling er hævet.','muted'));box.append(area);}
 box.append(el('h2','Hændelser'));for(const event of [...(order.events||[])].reverse()){box.append(el('div',`${new Date(event.at).toLocaleString('da-DK')} · ${event.type}${event.version?` · version ${event.version}`:''}`,'event'));}}
$('gateway-test-form').onsubmit=async event=>{event.preventDefault();const button=$('send-gateway-test');if($('test-confirmation').value!=='TEST'){say('Skriv TEST præcis som vist for at sende testordren.');return;}button.disabled=true;button.setAttribute('aria-busy','true');say('Sender testordren til PF’s testmiljø …');try{const result=await (await api('/api/pf-orders/test','POST',{name:$('test-name').value.trim(),email:$('test-email').value.trim(),phone:$('test-phone').value.trim(),street:$('test-street').value.trim(),postalCode:$('test-postal').value.trim(),city:$('test-city').value.trim(),confirmation:$('test-confirmation').value})).json();$('test-confirmation').value='';await refresh();selectedId=result.id;await show(result.id);say(`Testordren ${result.purchaseOrderNumber} er modtaget af PF’s test-Gateway. Ingen betaling er oprettet.`);}catch(error){say(error.message);await refresh().catch(()=>{});}finally{button.disabled=false;button.removeAttribute('aria-busy');}};
$('login').onsubmit=async event=>{event.preventDefault();try{await api('/api/admin/login','POST',{username:$('username').value.trim(),password:$('password').value});$('password').value='';await refresh();}catch(error){$('password').value='';say(error.message);}};$('refresh').onclick=refresh;$('logout').onclick=async()=>{try{await api('/api/admin/logout','POST');}finally{location.href='/';}};$('filter').onchange=renderList;api('/api/admin/session').then(response=>response.json()).then(state=>{if(state.authenticated)refresh();}).catch(()=>{});
